  "q": "________ design focusses on the data itself, whereas ________ design focusses more on data type, how it is stored and accessed.",
  "opts": {
   "A": "ER-diagram, SQL",
   "B": "MySQL, Oracle",
   "C": "Physical, logical",
   "D": "Primary, secondary"
  },
  "ans": "C",
  "exp": "Only option C uses genuine database-design terminology (physical vs logical design), so it must be the intended answer, but the printed word order is suspect. Conceptually, logical design (ER modelling, normalization, schema) concerns the data itself independent of implementation, while physical design concerns how that data is actually stored on disk - data types, indexes, file organisation, access paths. As printed the blanks read 'Physical...logical' which is backwards from the standard textbook mapping, most likely an OCR/typesetting word-order slip. Options A, B and D substitute unrelated pairs (a diagramming notation, two RDBMS products, two key types) that never describe design phases at all.",
  "prov": "Official MPSC final answer key",
