  "exp": "802.11a operates in the 5 GHz band and, because higher frequencies attenuate faster and penetrate obstacles poorly, its usable range at its maximum data rate (54 Mbps) is quite short indoors — commonly cited as roughly 25-75 feet in Cisco/CCNA wireless comparison tables, versus the much longer ranges of 802.11b/g at their top speeds. Of the given choices, only (a) About 65-75 feet falls within that commonly quoted range; the larger distances in (b), (c), and (d) describe either lower-speed fallback range or other standards like 802.11b/g/n. This value varies across sources, so treat it as approximate.",
