  "srcKey": "TECH1_OFFICIAL",
  "no": 22,
  "paper": "TECH1_LEGACY",
  "unit": "2",
  "sub": "Software Development Approach: Incremental Development model",
  "q": "What is the major advantage of using Incremental Development Model?",
  "opts": {
   "A": "Customer can respond to each increment",
   "B": "Easier to test and debug",
   "C": "It is used when there is a need to get a product to the market early",
   "D": "Both (b) & (c)"
  },
  "ans": "D",
  "exp": "The incremental model delivers the system as a series of smaller, working builds rather than one big release. Because each increment is a small, self-contained piece of functionality, it is genuinely easier to test and debug (option b) than debugging one massive final system, and because usable functionality reaches users after just the first increment rather than waiting for the whole system, it is well suited to getting a product to market early (option c). Option (a), customer response to each increment, is a real benefit too, but the combined option (d) capturing both the testing/debugging ease and early market delivery is treated as the intended fuller answer here.",
  "prov": "Single solver (unverified — treat with caution)",
