  "exp": "Deciding the overall project road-map, including which SDLC model best fits the project's requirements, risk profile, and constraints, is a planning decision made during the System Analysis / requirements and feasibility stage, before any design work begins. Software Design (a) assumes the model and scope have already been chosen and instead works out the internal architecture; Coding (c) and Testing (d) are downstream implementation and verification activities that happen even later. This question's phrasing is a bit loosely worded, so the intended phase is inferred as System Analysis rather than stated with full certainty.",
