  "q": "What is the main purpose of integration testing?",
  "opts": {
   "A": "Design errors",
   "B": "Interface errors",
   "C": "Procedure errors",
   "D": "None of the above"
  },
  "ans": "B",
  "exp": "Integration testing focuses on verifying that independently developed and unit-tested modules work correctly when combined, specifically targeting errors at the interfaces between them -- mismatched parameters, incorrect data formats, wrong call sequences, and faulty assumptions about shared data. Design errors (A) are typically caught earlier through design reviews or later through system testing against the design spec, and 'procedure errors' (C) is not a standard testing category; integration testing's defining, distinguishing purpose is interface-level defect detection between modules.",
