  "sub": "Software Testing Fundamentals",
  "q": "Which of the following term describes testing?",
  "opts": {
   "A": "Finding broken code",
   "B": "Evaluating deliverable to find errors",
   "C": "A stage of all projects",
   "D": "None of the mentioned"
  },
  "ans": "B",
  "exp": "The widely used (IEEE-style) definition of software testing is the process of evaluating a system or its components/deliverables to find whether they satisfy specified requirements and to identify defects -- i.e. 'evaluating a deliverable to find errors', which is broader and more accurate than just 'finding broken code' (A), since testing also validates correct behavior and requirement conformance, not only failures. 'A stage of all projects' (C) is too vague and does not define what testing actually does, so it is not a definition at all.",
  "prov": "Two independent solvers agreed (no official key for this sitting)",
